class Solution {
  public int maxFreeTime(int eventTime, int[] startTime, int[] endTime) {
    int n = startTime.length;
    int[] gap = new int[n + 1];
    gap[0] = startTime[0];
    for (int i = 1; i < n; i++) gap[i] = startTime[i] - endTime[i - 1];
    gap[n] = eventTime - endTime[n - 1];
    int[] prefixMax = new int[n + 1], suffixMax = new int[n + 2];
    prefixMax[0] = gap[0];
    for (int i = 1; i <= n; i++) prefixMax[i] = Math.max(prefixMax[i - 1], gap[i]);
    for (int i = n; i >= 0; i--) suffixMax[i] = Math.max(suffixMax[i + 1], gap[i]);
    int best = 0;
    for (int i = 0; i < n; i++) {
      int duration = endTime[i] - startTime[i];
      int left = i >= 1 ? prefixMax[i - 1] : 0; // gaps not touching meeting i
      int right = i + 2 <= n ? suffixMax[i + 2] : 0;
      // the meeting either fits into another gap (all of its time frees up) or just slides aside
      int merged = gap[i] + gap[i + 1] + (Math.max(left, right) >= duration ? duration : 0);
      best = Math.max(best, merged);
    }
    return best;
  }
}
